#include "TestRecipes.h"
#include "DetailProcessing.h"
#include "WorkingColorSpace.h"
#include <QCoreApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <opencv2/imgproc.hpp>
#include <array>
#include <chrono>
#include <cmath>
#include <exception>
#include <iostream>
#include <stdexcept>

namespace {
#ifdef IPR_REFERENCE_CONTEXT
constexpr int Side=512;
constexpr const char *Rules="Neutral native reference context512 only; no denoising or pixel resampling";
#else
constexpr int Side=256;
constexpr const char *Rules="Production DetailProcessing::reduceNoise fullframe 0/50/100, optics off, CameraNeutral RAW calibrated; no experimental filter";
#endif
void require(bool value,const char *message) { if (!value) throw std::runtime_error(message); }

QJsonArray writeCrops(const cv::Mat &rgb,QFile &pixels)
{
    require(!rgb.empty() && rgb.type()==CV_32FC3,"Invalid RGB image");
    QJsonArray rectangles;
    for (const double fy:{.2,.5,.8}) for (const double fx:{.2,.5,.8}) {
        const cv::Rect r(int(std::lround(fx*rgb.cols))-Side/2,int(std::lround(fy*rgb.rows))-Side/2,Side,Side);
        require((r&cv::Rect(0,0,rgb.cols,rgb.rows))==r,"Outside RGB crop");
        std::array<cv::Mat,3> planes;
        for (auto &p:planes) p.create(Side,Side,CV_32F);
        for(int y=0;y<Side;++y) {
            const auto *source=rgb.ptr<cv::Vec3f>(y+r.y)+r.x;
            for(int x=0;x<Side;++x) {
                planes[0].at<float>(y,x)=WorkingColor::luminance(source[x]);
                planes[1].at<float>(y,x)=source[x][0]-source[x][2];
                planes[2].at<float>(y,x)=source[x][1]-.5f*(source[x][0]+source[x][2]);
            }
        }
        for(const auto &p:planes) {
            require(cv::checkRange(p) && p.isContinuous(),"Invalid output plane");
            const qint64 count=qint64(p.total()*p.elemSize());
            require(pixels.write(reinterpret_cast<const char *>(p.data),count)==count,"Incomplete plane output");
        }
        rectangles.append(QJsonArray{r.x,r.y,r.width,r.height});
    }
    return rectangles;
}
}

int main(int argc,char **argv)
{
    QCoreApplication app(argc,argv);
    try {
        require(argc==3,"Usage: iprBurstControls output-prefix input-raw");
        cv::setNumThreads(4);
        const auto args=app.arguments();const QString prefix=args[1],path=args[2];
        const auto loaded=TestRecipes::load(path);
        const auto settings=TestRecipes::neutral(loaded);
        const auto image=ImageEditor::renderLinear(loaded.image,settings);
        require(!image.isNull(),"Native opening failed");
        cv::Mat original;cv::cvtColor(image.linearRgba,original,cv::COLOR_RGBA2RGB);
        QFile pixels(prefix+".f32");require(pixels.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Cannot create pixels");
        QJsonArray stages;QJsonArray rectangles;
        for (const int strength:{0,50,100}) {
#ifdef IPR_REFERENCE_CONTEXT
            if (strength!=0) continue;
#endif
            const auto start=std::chrono::steady_clock::now();
            cv::Mat rgb=original.clone();
            DetailProcessing::reduceNoise(rgb,{strength,strength});
            const double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();
            rectangles=writeCrops(rgb,pixels);
            stages.append(QJsonObject{{"strength",strength},{"denoise_ms",ms}});
        }
        pixels.close();
        const QJsonObject result{{"raw",path},{"sha256",TestRecipes::sha256(path)},
            {"declaration",TestRecipes::declaration(loaded,settings,path,"bruit","neutral",0.,path)},
            {"width",original.cols},{"height",original.rows},{"rectangles",rectangles},{"stages",stages},
            {"side",Side},{"layout","native-endian IEEEfloat32 stages/ROIs9/planesYCoCg3/rowsSide/colsSide"},
            {"rules",Rules}};
        QFile metadata(prefix+".json");require(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Cannot create metadata");
        const auto bytes=QJsonDocument(result).toJson(QJsonDocument::Compact);
        require(metadata.write(bytes)==bytes.size(),"Incomplete metadata");return 0;
    } catch(const std::exception &e) {std::cerr<<e.what()<<'\n';return 1;}
}
